function maxAncestorDiff(root: TreeNode | null): number {
    const dfs = (root: TreeNode | null, mi: number, mx: number): void => {
        if (!root) {
            return;
        }
        ans = Math.max(ans, Math.abs(root.val - mi), Math.abs(root.val - mx));
        mi = Math.min(mi, root.val);
        mx = Math.max(mx, root.val);
        dfs(root.left, mi, mx);
        dfs(root.right, mi, mx);
    };
    let ans: number = 0;
    dfs(root, root.val, root.val);
    return ans;
}

maximum-frequency-stack.solution:
class FreqStack {
  private freq = new Map<number, number>();
  private groups = new Map<number, number[]>();
  private maxFreq = 0;

  push(val: number): void {
    const f = (this.freq.get(val) ?? 0) + 1;
    this.freq.set(val, f);
    this.maxFreq = Math.max(this.maxFreq, f);
    if (!this.groups.has(f)) this.groups.set(f, []);
    this.groups.get(f)!.push(val);
  }

  pop(): number {
    const g = this.groups.get(this.maxFreq)!;
    const val = g.pop()!;
    this.freq.set(val, this.maxFreq - 1);
    if (g.length === 0) this.maxFreq--;
    return val;
  }
}

