        const [a, b] = edges[i];
        g[a].push([b, i]);
        g[b].push([a, i]);
    }
    const ans: number[] = [];
    const dfs = (a: number, fa: number): boolean => {
        let rev = start[a] !== target[a];
        for (const [b, i] of g[a]) {
