/**
 * Definition for a binary tree node.
 * class TreeNode {
 *     val: number
 *     left: TreeNode | null
 *     right: TreeNode | null
 *     constructor(val?: number, left?: TreeNode | null, right?: TreeNode | null) {
 *         this.val = (val===undefined ? 0 : val)
 *         this.left = (left===undefined ? null : left)
 *         this.right = (right===undefined ? null : right)
 *     }
 * }
 */
function isSubtree(root: TreeNode | null, subRoot: TreeNode | null): boolean {
    const same = (p: TreeNode | null, q: TreeNode | null): boolean => {
        if (!p || !q) {
            return p === q;
        }
        return p.val === q.val && same(p.left, q.left) && same(p.right, q.right);
    };
    if (!root) {
        return false;
    }
    return same(root, subRoot) || isSubtree(root.left, subRoot) || isSubtree(root.right, subRoot);
}

sudoku-solver.solution:
function solveSudoku(board: string[][]): void {
  const rows = Array.from({ length: 9 }, () => new Set<string>());
  const cols = Array.from({ length: 9 }, () => new Set<string>());
  const boxes = Array.from({ length: 9 }, () => new Set<string>());
  const empties: [number, number][] = [];
  for (let r = 0; r < 9; r++)
    for (let c = 0; c < 9; c++) {
      const v = board[r][c];
      if (v === '.') { empties.push([r, c]); continue; }
      rows[r].add(v); cols[c].add(v); boxes[((r / 3) | 0) * 3 + ((c / 3) | 0)].add(v);
    }
  const dfs = (k: number): boolean => {
    if (k === empties.length) return true;
    const [r, c] = empties[k];
    const b = ((r / 3) | 0) * 3 + ((c / 3) | 0);
    for (let d = 1; d <= 9; d++) {
      const v = String(d);
      if (rows[r].has(v) || cols[c].has(v) || boxes[b].has(v)) continue;
      board[r][c] = v; rows[r].add(v); cols[c].add(v); boxes[b].add(v);
      if (dfs(k + 1)) return true;
      board[r][c] = '.'; rows[r].delete(v); cols[c].delete(v); boxes[b].delete(v);
    }
    return false;
  };
  dfs(0);
}

