function f(x: number): number {
    const nums: number[] = [];
    while (x > 0) {
        nums.push(x % 10);
        x = Math.floor(x / 10);
    }
    const m = nums.length;
    if (m < 3) return 0;

    let s = 0;
    for (let i = 1; i < m - 1; i++) {
        if (
            (nums[i] > nums[i - 1] && nums[i] > nums[i + 1]) ||
            (nums[i] < nums[i - 1] && nums[i] < nums[i + 1])
